<template><aside class="side"><header><div><b>Fuel forecourt till</b><small>Quick volume sale</small></div><span>FUEL</span></header><label>Fuel grade<select v-model="grade"><option>Petrol</option><option>Diesel</option><option>Kerosene</option></select></label><label>Price per litre (KES)<input v-model.number="price" type="number" min="0.01" step="0.01" /></label><div class="volume"><button @click="litres=Math.max(0,litres-1)">−</button><label>Litres<input v-model.number="litres" type="number" min="0.01" step="0.01" /></label><button @click="litres=Number(litres)+1">+</button></div><div class="total"><span>Estimated line total</span><strong>KES {{ total.toLocaleString(undefined,{minimumFractionDigits:2,maximumFractionDigits:2}) }}</strong></div><button class="add" @click="addToCart">Add fuel to till</button><small class="note">Confirm actual pump delivery before taking payment. Price is configured for this till session.</small></aside></template>
<script setup>
import { computed, ref } from 'vue'
const grade=ref('Petrol'),price=ref(0),litres=ref(10)
const total=computed(()=>Number(price.value||0)*Number(litres.value||0))
function addToCart(){if(Number(price.value)<=0||Number(litres.value)<=0)return;const item={id:`fuel-${Date.now()}`,name:`${grade.value} · ${Number(litres.value).toFixed(2)} L`,sku:`FUEL-${grade.value.toUpperCase()}`,price_minor:Math.round(total.value*100),unit_price_minor:Math.round(total.value*100),quantity:1,kind:'service',fuel_grade:grade.value,litres:Number(litres.value)};window.dispatchEvent(new CustomEvent('pos:add-item',{detail:item}));window.dispatchEvent(new CustomEvent('pos:notification',{detail:{message:`Added ${item.name} to till · KES ${total.value.toFixed(2)}`,type:'success'}}))}
</script>
<style scoped>
.side{display:grid;gap:12px;padding:15px;border:1px solid #dce8df;border-radius:12px;background:#fff}.side header{display:flex;align-items:center;justify-content:space-between;padding-bottom:10px;border-bottom:1px solid #edf2ed}.side header div{display:grid;gap:4px}.side header b{font-size:13px;color:#173d2d}.side header small,.note{color:#728078;font-size:10px}.side header span{padding:4px 7px;border-radius:5px;background:#e8f3ea;color:#17623b;font-size:9px;font-weight:800}.side>label,.volume label{display:grid;gap:5px;color:#56635b;font-size:10px;font-weight:700}.side select,.side input{width:100%;box-sizing:border-box;padding:8px;border:1px solid #d4ddd6;border-radius:6px;background:#fff}.volume{display:flex;align-items:end;gap:7px}.volume label{flex:1}.volume button{width:34px;height:34px;border:1px solid #cbd8ce;border-radius:6px;background:#f6faf6;color:#17623b;font-size:18px;cursor:pointer}.total{display:grid;gap:5px;padding:11px;border-radius:8px;background:#f3f8f3}.total span{color:#68766d;font-size:10px}.total strong{font-size:18px;color:#173d2d}.add{padding:10px;border:0;border-radius:7px;background:#16734e;color:white;font-weight:700;cursor:pointer}.note{line-height:1.4}
</style>
